package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/gorilla/websocket"
	_ "github.com/lib/pq"
)

var db *sql.DB
var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type QueryMessage struct {
	Action  string `json:"action"`
	Channel string `json:"channel"`
	Filter  string `json:"filter"`
	UserID  string `json:"user_id"`
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		var msg QueryMessage
		err := conn.ReadJSON(&msg)
		if err != nil {
			log.Printf("read error: %v", err)
			break
		}

		switch msg.Action {
		case "subscribe":
			handleSubscribe(conn, msg)
		case "query_history":
			handleQueryHistory(conn, msg)
		case "search_users":
			handleSearchUsers(conn, msg)
		default:
			conn.WriteJSON(map[string]string{"error": "unknown action"})
		}
	}
}

func handleSubscribe(conn *websocket.Conn, msg QueryMessage) {
	// Subscription logic - channel name validated against allowlist
	allowedChannels := []string{"notifications", "updates", "alerts"}
	valid := false
	for _, ch := range allowedChannels {
		if ch == msg.Channel {
			valid = true
			break
		}
	}
	if !valid {
		conn.WriteJSON(map[string]string{"error": "invalid channel"})
		return
	}
	conn.WriteJSON(map[string]string{"status": "subscribed", "channel": msg.Channel})
}

func handleQueryHistory(conn *websocket.Conn, msg QueryMessage) {
	// Build query with user-supplied filter - VULNERABLE
	baseQuery := "SELECT id, message, created_at FROM chat_history WHERE channel_id = '%s'"
	query := fmt.Sprintf(baseQuery, msg.Channel)

	if msg.Filter != "" {
		// Filter is directly concatenated - SQL injection vector
		query += " AND message LIKE '%" + msg.Filter + "%'"
	}

	if msg.UserID != "" {
		query += fmt.Sprintf(" AND user_id = '%s'", msg.UserID)
	}

	query += " ORDER BY created_at DESC LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		conn.WriteJSON(map[string]string{"error": "query failed"})
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	for rows.Next() {
		var id int
		var message, createdAt string
		rows.Scan(&id, &message, &createdAt)
		results = append(results, map[string]interface{}{
			"id": id, "message": message, "created_at": createdAt,
		})
	}
	conn.WriteJSON(map[string]interface{}{"action": "history", "data": results})
}

func handleSearchUsers(conn *websocket.Conn, msg QueryMessage) {
	// Parameterized query - safe
	rows, err := db.Query("SELECT id, username FROM users WHERE username ILIKE $1 LIMIT 20",
		"%"+strings.ReplaceAll(msg.Filter, "%", "\\%")+"%")
	if err != nil {
		conn.WriteJSON(map[string]string{"error": "search failed"})
		return
	}
	defer rows.Close()

	var users []map[string]interface{}
	for rows.Next() {
		var id int
		var username string
		rows.Scan(&id, &username)
		users = append(users, map[string]interface{}{"id": id, "username": username})
	}
	conn.WriteJSON(map[string]interface{}{"action": "users", "data": users})
}

func main() {
	dsn := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	http.HandleFunc("/ws", handleWebSocket)
	log.Println("WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
